    difficulty: { concept: 3, implementation: 3, recall: 3 },
    estimatedMinutes: 12,
    prompt: "A queue serves the oldest item first, which makes it the right structure for anything that **expires** in arrival order.\n\n`times` is a list of strictly increasing timestamps. For each ping, report how many pings happened within the last `window` time units — that is, in the inclusive range `[time - window, time]`.\n\n`([1, 100, 3001, 3002], 3000)` gives `[1, 2, 3, 3]`.",
    exportName: "recent_counts",
    scaffolds: { L1: "from collections import deque\n\ndef recent_counts(times, window):\n    pass", L2: "from collections import deque\n\ndef recent_counts(times, window):\n    pass", L3: "from collections import deque\n\ndef recent_counts(times, window):\n    pass", L4: "" },
