    solution: "def reachable_from(vertex_count, edges, start):\n    adjacency = [[] for _ in range(vertex_count)]\n    for source, target in edges:\n        adjacency[source].append(target)\n    seen = set()\n    stack = [start] if vertex_count else []\n    while stack:\n        vertex = stack.pop()\n        if vertex in seen:\n            continue\n        seen.add(vertex)\n        stack.extend(adjacency[vertex])\n    return sorted(seen)",
