    solution: "def all_pairs(vertex_count, edges):\n    best = [[None] * vertex_count for _ in range(vertex_count)]\n    for vertex in range(vertex_count):\n        best[vertex][vertex] = 0\n    for source, target, weight in edges:\n        current = best[source][target]\n        if current is None or weight < current:\n            best[source][target] = weight\n    for middle in range(vertex_count):\n        for row in range(vertex_count):\n            if best[row][middle] is None:\n                continue\n            for col in range(vertex_count):\n                if best[middle][col] is None:\n                    continue\n                candidate = best[row][middle] + best[middle][col]\n                if best[row][col] is None or candidate < best[row][col]:\n                    best[row][col] = candidate\n    return best",
    language: "python",
