    solution: "def split_impurity(left, right):\n    def gini(part):\n        if not part:\n            return 0.0\n        counts = {}\n        for label in part:\n            counts[label] = counts.get(label, 0) + 1\n        return 1 - sum((c / len(part)) ** 2 for c in counts.values())\n    total = len(left) + len(right)\n    if total == 0:\n        return 0.0\n    return (len(left) * gini(left) + len(right) * gini(right)) / total",
