    solution: "def neighbourhood_overlap(original, embedded, k):\n    n = len(original)\n    if n != len(embedded) or k < 1 or k >= n:\n        return None\n    def neighbours(points, i):\n        order = sorted(\n            (j for j in range(n) if j != i),\n            key=lambda j: (sum((a - b) ** 2 for a, b in zip(points[i], points[j])), j),\n        )\n        return set(order[:k])\n    total = 0.0\n    for i in range(n):\n        kept = neighbours(original, i) & neighbours(embedded, i)\n        total += len(kept) / k\n    return total / n",
