    requires: [],
    difficulty: { concept: 4, implementation: 3, recall: 3 },
    estimatedMinutes: 12,
    prompt: "Precision asks how many flagged cases were right; recall asks how many real positives were caught. F1 is their harmonic mean, which stays low whenever either side is weak.\n\nReturn `(precision, recall, f1)` for binary labels where `1` is positive. Any metric whose denominator is zero is `0.0`.\n\nA model that flags nothing scores `(0.0, 0.0, 0.0)` however accurate it looks.",
    exportName: "prf",
    scaffolds: { L1: "def prf(truth, predicted):\n    pass", L2: "def prf(truth, predicted):\n    pass", L3: "def prf(truth, predicted):\n    pass", L4: "" },
