    difficulty: { concept: 4, implementation: 4, recall: 4 },
    estimatedMinutes: 13,
    prompt: "A model outputs scores, not decisions. The **threshold** turns one into the other, and moving it trades precision against recall without retraining anything.\n\nReturn the lowest threshold from `candidates` whose precision is at least `min_precision`, flagging every case whose score is greater than or equal to it. Return `None` if none qualify.\n\nThe lowest qualifying threshold is the one that keeps the most recall while honouring the precision floor.",
    exportName: "choose_threshold",
    scaffolds: { L1: "def choose_threshold(truth, scores, candidates, min_precision):\n    pass", L2: "def choose_threshold(truth, scores, candidates, min_precision):\n    pass", L3: "def choose_threshold(truth, scores, candidates, min_precision):\n    pass", L4: "" },
