      { name: "a low bar already qualifies", code: "assert fn([1,1,0], [0.9,0.8,0.1], [0.5,0.9], 1.0) == 0.5", hidden: false },
      { name: "nothing reaches the floor", code: "assert fn([0,0], [0.9,0.8], [0.5], 0.5) is None", hidden: false },
      { name: "thresholds with no flags are skipped", code: "assert fn([1], [0.4], [0.9, 0.2], 1.0) == 0.2", hidden: false },
      { name: "lowest qualifying keeps most recall", code: "assert fn([1,1,0], [0.9,0.6,0.1], [0.2,0.5,0.95], 1.0) == 0.2", hidden: true }
