    id: "py.ex.ac.m6_4.l3",
    kind: "problem",
    tier: "rep",
    lesson: "py.ac.m6_4.l3",
    title: "Design the state a cooldown forces on you",
    teaches: ["py.algo.dp-state-design"],
    requires: [],
    difficulty: { concept: 5, implementation: 5, recall: 5 },
