    prompt: "Return the largest sum of a contiguous run in a **circular** list, where a run may wrap past the end and continue from the front. Each element may be used at most once.\n\nA wrapping run is exactly the total minus some non-wrapping run in the middle, so the smallest such run gives the best wrap. Run Kadane's twice: once for the maximum and once for the minimum.\n\nGuard the all-negative case, where subtracting the minimum would leave an empty run.",
    exportName: "max_circular",
    scaffolds: { L1: "def max_circular(values):\n    pass", L2: "def max_circular(values):\n    pass", L3: "def max_circular(values):\n    pass", L4: "" },
    tests: [
      { name: "no wrap needed", code: "assert fn([1, -2, 3, -2]) == 3", hidden: false },
      { name: "wrapping wins", code: "assert fn([5, -3, 5]) == 10", hidden: false },
      { name: "all negative", code: "assert fn([-3, -2, -3]) == -2", hidden: false },
      { name: "a tie between wrap and no wrap", code: "assert fn([3, -1, 2, -1]) == 4", hidden: false },
      { name: "all negative, ending largest", code: "assert fn([-2, -3, -1]) == -1", hidden: false },
      { name: "single element", code: "assert fn([7]) == 7", hidden: true }
    ],
    hints: [
      { rung: 0, text: "Track the best and the worst run in the same pass." },
      { rung: 1, text: "The best wrapping run is the total minus the worst non-wrapping run." },
      { rung: 2, text: "If every value is negative, the worst run is the whole list and the wrap answer is empty." }
    ],
    solution: "def max_circular(values):\n    total = sum(values)\n    best = running = values[0]\n    worst = falling = values[0]\n    for value in values[1:]:\n        running = max(value, running + value)\n        best = max(best, running)\n        falling = min(value, falling + value)\n        worst = min(worst, falling)\n    if best < 0:\n        return best\n    return max(best, total - worst)",
    language: "python",
