    prompt: "A graph is a dict mapping each node to a list of `(parent, local_derivative)` pairs. Return a dict of the gradient of `root` with respect to every reachable node.\n\nVisit nodes in **reverse topological order** so a node runs only once every consumer has contributed, and **accumulate** rather than assign, because a node may feed several consumers.\n\nThe root's own gradient is `1.0`.",
    exportName: "backward",
    scaffolds: { L1: "def backward(graph, root):\n    pass", L2: "def backward(graph, root):\n    pass", L3: "def backward(graph, root):\n    pass", L4: "" },
    tests: [
      { name: "a straight chain multiplies", code: "g = {'y': [('h', 3.0)], 'h': [('x', 2.0)]}\nout = fn(g, 'y')\nassert out['y'] == 1.0 and out['h'] == 3.0 and out['x'] == 6.0", hidden: false },
      { name: "a shared node accumulates", code: "g = {'y': [('a', 1.0), ('b', 1.0)], 'a': [('x', 2.0)], 'b': [('x', 5.0)]}\nassert fn(g, 'y')['x'] == 7.0", hidden: false },
      { name: "squaring adds the same path twice", code: "g = {'y': [('x', 3.0), ('x', 3.0)]}\nassert fn(g, 'y')['x'] == 6.0", hidden: false },
      { name: "a node reached by two depths is still correct", code: "g = {'d': [('c', 1.0), ('a', 10.0)], 'c': [('a', 2.0), ('b', 1.0)]}\nout = fn(g, 'd')\nassert out['a'] == 12.0 and out['b'] == 1.0", hidden: false },
      { name: "a lone root", code: "assert fn({}, 'x') == {'x': 1.0}", hidden: false },
      { name: "every reachable node is reported", code: "g = {'y': [('a', 1.0)], 'a': [('x', 1.0)]}\nassert set(fn(g, 'y')) == {'y', 'a', 'x'}", hidden: true }
    ],
    hints: [
      { rung: 0, text: "Build the forward order first, then walk it in reverse." },
      { rung: 1, text: "Seed every gradient at zero and set the root's to one." },
      { rung: 2, text: "Use plus-equals so a node fed by several consumers collects all of them." }
    ],
    solution: "def backward(graph, root):\n    order, seen = [], set()\n\n    def visit(node):\n        if node in seen:\n            return\n        seen.add(node)\n        for parent, _ in graph.get(node, ()):\n            visit(parent)\n        order.append(node)\n\n    visit(root)\n    grads = {node: 0.0 for node in order}\n    grads[root] = 1.0\n    for node in reversed(order):\n        for parent, local in graph.get(node, ()):\n            grads[parent] += local * grads[node]\n    return grads",
    language: "python",
