    difficulty: { concept: 5, implementation: 5, recall: 4 },
    estimatedMinutes: 16,
    prompt: "Return `(lcs_length, edit_distance)` for the two strings `a` and `b`.\n\nBoth use the same state: how much of each string has been consumed. Matching characters move diagonally in both; the difference is that one takes a **maximum** over drops and the other a **minimum** over insert, delete and substitute.\n\nSeed the edit-distance borders with the prefix length, since turning a prefix into nothing costs one edit per character.",
    exportName: "compare_sequences",
    scaffolds: { L1: "def compare_sequences(a, b):\n    pass", L2: "def compare_sequences(a, b):\n    pass", L3: "def compare_sequences(a, b):\n    pass", L4: "" },
    tests: [
      { name: "a subsequence and three edits", code: "assert fn('abcde', 'ace') == (3, 2)", hidden: false },
      { name: "the textbook pair", code: "assert fn('horse', 'ros') == (2, 3)", hidden: false },
      { name: "longer textbook pair", code: "assert fn('intention', 'execution') == (5, 5)", hidden: false },
      { name: "nothing in common", code: "assert fn('abc', 'def') == (0, 3)", hidden: false },
      { name: "empty strings", code: "assert fn('', 'abc') == (0, 3) and fn('', '') == (0, 0)", hidden: false },
      { name: "identical strings", code: "assert fn('same', 'same') == (4, 0)", hidden: true }
    ],
    hints: [
      { rung: 0, text: "Both loops index the strings with i minus one and j minus one." },
      { rung: 1, text: "The subsequence grid takes the better of dropping from each side on a mismatch." },
      { rung: 2, text: "The distance row must start at i, the cost of deleting that whole prefix." }
    ],
    solution: "def compare_sequences(a, b):\n    common = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]\n    for i in range(1, len(a) + 1):\n        for j in range(1, len(b) + 1):\n            if a[i - 1] == b[j - 1]:\n                common[i][j] = common[i - 1][j - 1] + 1\n            else:\n                common[i][j] = max(common[i - 1][j], common[i][j - 1])\n    previous = list(range(len(b) + 1))\n    for i in range(1, len(a) + 1):\n        current = [i] + [0] * len(b)\n        for j in range(1, len(b) + 1):\n            cost = 0 if a[i - 1] == b[j - 1] else 1\n            current[j] = min(previous[j] + 1,\n                             current[j - 1] + 1,\n                             previous[j - 1] + cost)\n        previous = current\n    return (common[len(a)][len(b)], previous[len(b)])",
    language: "python",
