      { name: "a lone star matches anything", code: "assert fn('aa', '*') is True and fn('', '*') is True", hidden: false },
      { name: "question marks match one each", code: "assert fn('cb', '?a') is False and fn('cb', '?b') is True", hidden: false },
      { name: "stars around a literal", code: "assert fn('adceb', '*a*b') is True and fn('acdcb', 'a*c?b') is False", hidden: false },
      { name: "stars alone match the empty text", code: "assert fn('', '***') is True and fn('', 'a') is False", hidden: false },
      { name: "greedy matching would fail here", code: "assert fn('aab', '*ab') is True", hidden: true }
