    requires: [],
    difficulty: { concept: 5, implementation: 5, recall: 4 },
    estimatedMinutes: 16,
    prompt: "Return every start index where `pattern` occurs in `text`, using a rolling polynomial hash.\n\nThe window updates in constant time: subtract the outgoing character's contribution, shift the rest up one place, then add the incoming character. **Verify** with a real character comparison whenever the hashes agree, because different strings can share a hash.\n\nOverlapping occurrences all count. An empty pattern, or one longer than the text, returns an empty list.",
    exportName: "rabin_karp",
    scaffolds: { L1: "def rabin_karp(text, pattern, base=256, mod=1_000_000_007):\n    pass", L2: "def rabin_karp(text, pattern, base=256, mod=1_000_000_007):\n    pass", L3: "def rabin_karp(text, pattern, base=256, mod=1_000_000_007):\n    pass", L4: "" },
