    difficulty: { concept: 4, implementation: 5, recall: 5 },
    estimatedMinutes: 16,
    prompt: "`records` is a list of `(group, label)` pairs. Split it so that **every record sharing a group lands on the same side**, holding out roughly `fraction` of the groups.\n\nTake groups in sorted order and assign the first `round(len(groups) * fraction)` of them to the held-out side. Return `(train, held_out, leaked)`, where `leaked` is the number of groups appearing on both sides.\n\nA correct split always reports zero leaked groups. Raise `ValueError` unless `fraction` lies between 0 and 1.",
    exportName: "grouped_split",
    scaffolds: { L1: "def grouped_split(records, fraction=0.2):\n    pass", L2: "def grouped_split(records, fraction=0.2):\n    pass", L3: "def grouped_split(records, fraction=0.2):\n    pass", L4: "" },
    tests: [
      { name: "no group straddles the split", code: "records = [(p, p % 2) for p in range(10) for _ in range(3)]\ntrain, held, leaked = fn(records, 0.2)\nassert leaked == 0", hidden: false },
      { name: "every record is kept exactly once", code: "records = [(p, p % 2) for p in range(10) for _ in range(3)]\ntrain, held, _ = fn(records, 0.2)\nassert len(train) + len(held) == len(records)", hidden: false },
      { name: "the fraction applies to groups, not records", code: "records = [('a', 0)] * 50 + [('b', 1), ('c', 1), ('d', 1), ('e', 1)]\ntrain, held, _ = fn(records, 0.2)\nassert len({g for g, _ in held}) == 1", hidden: false },
      { name: "a fraction of zero holds nothing out", code: "records = [(1, 0), (2, 1)]\ntrain, held, leaked = fn(records, 0.0)\nassert held == [] and len(train) == 2 and leaked == 0", hidden: false },
      { name: "a fraction of one holds everything out", code: "records = [(1, 0), (2, 1)]\ntrain, held, _ = fn(records, 1.0)\nassert train == [] and len(held) == 2", hidden: false },
      { name: "an out-of-range fraction is rejected", code: "try:\n    fn([(1, 0)], 1.5)\n    raise AssertionError('should have raised')\nexcept ValueError:\n    pass", hidden: true }
    ],
    hints: [
      { rung: 0, text: "Collect the distinct groups first, then decide which of them are held out." },
      { rung: 1, text: "Assign whole groups, never individual records." },
      { rung: 2, text: "The leak count is the size of the intersection of the two group sets." }
    ],
    solution: "def grouped_split(records, fraction=0.2):\n    if not 0 <= fraction <= 1:\n        raise ValueError('fraction must lie between 0 and 1')\n    groups = sorted({group for group, _ in records})\n    cut = round(len(groups) * fraction)\n    held_groups = set(groups[:cut])\n    train = [r for r in records if r[0] not in held_groups]\n    held_out = [r for r in records if r[0] in held_groups]\n    leaked = len({g for g, _ in train} & {g for g, _ in held_out})\n    return (train, held_out, leaked)",
