    id: "py.ex.mc.m5_2.l3",
    kind: "problem",
    tier: "rep",
    lesson: "py.mc.m5_2.l3",
    title: "Score a mask by class, not by pixel",
    teaches: ["py.ml.segmentation"],
    requires: [],
    difficulty: { concept: 4, implementation: 5, recall: 4 },
    estimatedMinutes: 15,
    prompt: "`predicted` and `truth` are equal-shaped grids of class ids. Return `(pixel_accuracy, mean_iou)`, both rounded to six places.\n\nPixel accuracy is the fraction of positions that agree, which a background-dominated image makes flattering. Mean overlap averages, over every class appearing in either grid, the intersection over the union for that class.\n\nA class present in neither grid is skipped. Raise `ValueError` when the shapes differ or a grid is empty.",
    exportName: "score_masks",
    scaffolds: { L1: "def score_masks(predicted, truth):\n    pass", L2: "def score_masks(predicted, truth):\n    pass", L3: "def score_masks(predicted, truth):\n    pass", L4: "" },
    tests: [
      { name: "a perfect prediction", code: "grid = [[0, 0, 1], [0, 1, 1]]\nassert fn(grid, grid) == (1.0, 1.0)", hidden: false },
      { name: "predicting background everywhere flatters accuracy", code: "truth = [[0, 0, 0, 0], [0, 0, 0, 1]]\npred = [[0, 0, 0, 0], [0, 0, 0, 0]]\naccuracy, mean = fn(pred, truth)\nassert accuracy == 0.875 and mean < 0.5", hidden: false },
      { name: "a class present in neither is skipped", code: "truth = [[0, 1]]\npred = [[0, 1]]\nassert fn(pred, truth)[1] == 1.0", hidden: false },
      { name: "completely wrong", code: "assert fn([[1, 1]], [[0, 0]]) == (0.0, 0.0)", hidden: false },
      { name: "a single pixel", code: "assert fn([[3]], [[3]]) == (1.0, 1.0)", hidden: false },
      { name: "mismatched shapes are rejected", code: "try:\n    fn([[0, 1]], [[0]])\n    raise AssertionError('should have raised')\nexcept ValueError:\n    pass", hidden: true }
    ],
    hints: [
      { rung: 0, text: "Flatten both grids once and reuse the flat lists." },
      { rung: 1, text: "A class's union counts positions where either grid holds that class." },
      { rung: 2, text: "Average the per-class scores, not the per-pixel ones." }
    ],
    solution: "def score_masks(predicted, truth):\n    if not predicted or not truth or len(predicted) != len(truth):\n        raise ValueError('grids must be non-empty and the same shape')\n    if any(len(p) != len(t) for p, t in zip(predicted, truth)):\n        raise ValueError('grids must be the same shape')\n    flat_p = [v for row in predicted for v in row]\n    flat_t = [v for row in truth for v in row]\n    agree = sum(1 for p, t in zip(flat_p, flat_t) if p == t)\n    accuracy = agree / len(flat_t)\n    scores = []\n    for label in sorted(set(flat_p) | set(flat_t)):\n        inter = sum(1 for p, t in zip(flat_p, flat_t) if p == label and t == label)\n        union = sum(1 for p, t in zip(flat_p, flat_t) if p == label or t == label)\n        if union:\n            scores.append(inter / union)\n    mean = sum(scores) / len(scores) if scores else 0.0\n    return (round(accuracy, 6), round(mean, 6))",
    language: "python",
