    solution: "import math\n\ndef scaled_attention(queries, keys, values):\n    if not keys or len(keys) != len(values):\n        raise ValueError('keys and values must match and be non-empty')\n    scale = math.sqrt(len(keys[0]))\n    all_weights = []\n    output = []\n    for query in queries:\n        scores = [sum(q * k for q, k in zip(query, key)) / scale for key in keys]\n        top = max(scores)\n        raw = [math.exp(s - top) for s in scores]\n        total = sum(raw)\n        weights = [w / total for w in raw]\n        all_weights.append([round(w, 6) for w in weights])\n        output.append([round(sum(w * v[i] for w, v in zip(weights, values)), 6)\n                       for i in range(len(values[0]))])\n    return (all_weights, output)",
