      { name: "an uneven split is rejected", code: "for args in (([0.0] * 5, 2), ([0.0] * 4, 0)):\n    try:\n        fn(*args)\n        raise AssertionError('should have raised')\n    except ValueError:\n        pass", hidden: true }
