    solution: "def modular(base, exponent, modulus):\n    if modulus < 2 or exponent < 0:\n        raise ValueError('invalid modulus or exponent')\n    result = 1\n    current = base % modulus\n    remaining = exponent\n    steps = 0\n    while remaining:\n        if remaining & 1:\n            result = result * current % modulus\n        current = current * current % modulus\n        remaining >>= 1\n        steps += 1\n\n    def extended(p, r):\n        if r == 0:\n            return (p, 1, 0)\n        divisor, x, y = extended(r, p % r)\n        return (divisor, y, x - (p // r) * y)\n\n    divisor, x, _ = extended(base % modulus, modulus)\n    inverse = None if divisor != 1 else x % modulus\n    return (result, inverse, steps)",
