    solution: "def bit_op(value, position, operation):\n    if position < 0:\n        raise ValueError('position must not be negative')\n    mask = 1 << position\n    if operation == 'test':\n        return bool(value & mask)\n    if operation == 'set':\n        return value | mask\n    if operation == 'clear':\n        return value & ~mask\n    if operation == 'toggle':\n        return value ^ mask\n    raise ValueError('unknown operation')",
